/* eslint-disable @next/next/no-img-element */
// AVIF/WebP generated by scripts/images.mjs into /images/generated/, original as fallback.
export function Picture({ src, alt, width, height, priority = false, className = "", sizes }: {
  src: string; alt: string; width: number; height: number; priority?: boolean; className?: string; sizes?: string;
}) {
  const base = src.replace(/^\/images\//, "/images/generated/").replace(/\.[^.]+$/, "");
  return (
    <picture>
      <source type="image/avif" srcSet={`${base}.avif`} sizes={sizes} />
      <source type="image/webp" srcSet={`${base}.webp`} sizes={sizes} />
      <img src={src} alt={alt} width={width} height={height} className={className}
        loading={priority ? "eager" : "lazy"} fetchPriority={priority ? "high" : "auto"} decoding="async" />
    </picture>
  );
}
